(* Rising-edge detection is performed in every scan so that a Start press is
   recognized once even when it remains held. *)
StartEdge := Start AND NOT StartPrev;
StartPrev := Start;
IF NOT EmergencyStop THEN
    StartEdge := FALSE;
END_IF;

(* Always clear outputs first. *)
MoveDown := FALSE;
MoveUp := FALSE;
MoveLeft := FALSE;
MoveRight := FALSE;
ActivateGrip := FALSE;
ActivateRelease := FALSE;

IF NOT EmergencyStop THEN
    StepActive := FALSE;
    StepIndex := 0;
    SingleCycleState := 0;
    ContinuousState := 0;
ELSE
    (* Manual mode *)
    IF ManualMode THEN
        MoveDown := DownButton AND NOT DownLimitSwitch;
        MoveUp := UpButton AND NOT UpLimitSwitch;
        MoveLeft := LeftButton AND NOT LeftLimitSwitch;
        MoveRight := RightButton AND NOT RightLimitSwitch;
        ActivateGrip := GripButton AND NOT GripLimitSwitch;
        ActivateRelease := ReleaseButton AND NOT ReleaseLimitSwitch;
    END_IF;

    (* Single step mode *)
    IF SingleStepMode THEN
        IF StartEdge THEN
           StepIndex := StepIndex + 1;
           IF StepIndex > 8 THEN StepIndex := 1; END_IF;
           StepActive := TRUE;
        END_IF;
        IF StepActive THEN
            CASE StepIndex OF
                1:
                    MoveDown := TRUE;
                    IF DownLimitSwitch THEN StepActive := FALSE; END_IF;
                2:
                    ActivateGrip := TRUE;
                    IF GripLimitSwitch THEN StepActive := FALSE; END_IF;
                3:
                    MoveUp := TRUE;
                    IF UpLimitSwitch THEN StepActive := FALSE; END_IF;
                4:
                    MoveRight := TRUE;
                    IF RightLimitSwitch THEN StepActive := FALSE; END_IF;
                5:
                    MoveDown := TRUE;
                    IF DownLimitSwitch THEN StepActive := FALSE; END_IF;
                6:
                    ActivateRelease := TRUE;
                    IF ReleaseLimitSwitch THEN StepActive := FALSE; END_IF;
                7:
                    MoveUp := TRUE;
                    IF UpLimitSwitch THEN StepActive := FALSE; END_IF;
                8:
                    MoveLeft := TRUE;
                    IF LeftLimitSwitch THEN StepActive := FALSE; END_IF;
            END_CASE;
        END_IF;
    ELSE
        StepActive := FALSE;
        StepIndex := 0;
    END_IF;

    (* Single cycle mode *)
    IF SingleCycleMode THEN
        CASE SingleCycleState OF
            0:
                IF StartEdge THEN
                    SingleCycleState := 1;
                END_IF;
            1:
                MoveDown := TRUE;
                IF DownLimitSwitch THEN
                    SingleCycleState := 2;
                END_IF;
            2:
                ActivateGrip := TRUE;
                IF GripLimitSwitch THEN
                    SingleCycleState := 3;
                END_IF;
            3:
                MoveUp := TRUE;
                IF UpLimitSwitch THEN
                    SingleCycleState := 4;
                END_IF;
            4:
                MoveRight := TRUE;
                IF RightLimitSwitch THEN
                    SingleCycleState := 5;
                END_IF;
            5:
                MoveDown := TRUE;
                IF DownLimitSwitch THEN
                    SingleCycleState := 6;
                END_IF;
            6:
                ActivateRelease := TRUE;
                IF ReleaseLimitSwitch THEN
                    SingleCycleState := 7;
                END_IF;
            7:
                MoveUp := TRUE;
                IF UpLimitSwitch THEN
                    SingleCycleState := 8;
                END_IF;
            8:
                MoveLeft := TRUE;
                IF LeftLimitSwitch THEN
                    SingleCycleState := 9;
                END_IF;
            9:
                IF StartEdge THEN
                    SingleCycleState := 1;
                END_IF;
        END_CASE;
    ELSE
        SingleCycleState := 0;
    END_IF;

    (* Continuous mode *)
    IF ContinuousMode THEN
        CASE ContinuousState OF
            0:
                IF StartEdge THEN
                    ContinuousState := 1;
                END_IF;
            1:
                MoveDown := TRUE;
                IF DownLimitSwitch THEN
                    ContinuousState := 2;
                END_IF;
            2:
                ActivateGrip := TRUE;
                IF GripLimitSwitch THEN
                    ContinuousState := 3;
                END_IF;
            3:
                MoveUp := TRUE;
                IF UpLimitSwitch THEN
                    ContinuousState := 4;
                END_IF;
            4:
