                IF ReleaseLimitSwitch THEN
                    ContinuousState := 7;
                END_IF;
            7:
                MoveUp := TRUE;
                IF UpLimitSwitch THEN
                    ContinuousState := 8;
                END_IF;
            8:
                MoveLeft := TRUE;
                IF LeftLimitSwitch THEN
                    ContinuousState := 1;
                END_IF;
        END_CASE;
    ELSE
        ContinuousState := 0;
    END_IF;
END_IF;
```

